contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}
    function run(uint amount) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (1) + (amount)); require(amount <= 1000000000000000000000000000000);
        require(amount > 0);
        require(address(this).balance >= amount + 1);
        // Give c extra Ether from a third party so its balance exceeds this caller's credit
        c.deposit{value: 1}(); if (__ESBMC_reverted()) return;
        c.withdrawAll(); if (__ESBMC_reverted()) return;
        uint extraBefore = address(c).balance + amount;
        // Now deposit our amount and snapshot balances
        c.deposit{value: amount}(); if (__ESBMC_reverted()) return;
        uint balBefore = address(this).balance;
        c.withdrawAll(); if (__ESBMC_reverted()) return;
        assert(address(this).balance - balBefore == amount && address(c).balance + amount == extraBefore);
    }
    receive() external payable {}
}

